        g.setFont(12.f);g.setColour(juce::Colour(0xff9c9c9c));g.drawText("v0.18 BETA / LIQUID GLASS",26,57,600,18,juce::Justification::centredLeft);g.drawText("Eleander Sanchez (Bodby Olwen)",650,57,446,18,juce::Justification::centredRight);g.setColour(look.accent);g.drawText(p.patchModified()?"MODIFICADO":"GUARDADO",410,57,220,18,juce::Justification::centredLeft);
        if(!assistantShowing&&!effectsTab.getToggleState()&&advancedShowing&&!bankTab.getToggleState()){g.setFont(11.f);g.setColour(juce::Colour(0xff9bacc0));g.drawText("OSC A",24,329,150,15,juce::Justification::centredLeft);g.drawText("OSC B",184,329,150,15,juce::Justification::centredLeft);g.drawText("MOTOR",344,329,170,15,juce::Justification::centredLeft);}
        if(!assistantShowing&&!bankTab.getToggleState()){g.setFont(13.f);g.setColour(look.accent);g.drawText(p.soundType(),208,130,424,24,juce::Justification::centredLeft);}

        if(!assistantShowing&&!bankTab.getToggleState()&&(p.fitting.load()||p.loading.load())){g.setColour(look.accent);g.fillRect(24.f,303.f,1072*p.fitProgress.load(),3.f);}
        g.setFont(12.f);g.setColour(juce::Colour(0xff9c9c9c));g.drawText("",970,350,126,23,juce::Justification::centredRight);
