        g.setColour(juce::Colour(0xff252525));g.drawHorizontalLine(644,24,1096);g.setColour(juce::Colour(0xffaaaaaa));g.drawText("A W S E D F T G Y H U J K  /  Z-X: octava  /  Esc: parar  /  MIDI "+juce::String(p.keyboardBase.load()),425,650,360,20,juce::Justification::centredLeft);g.drawText("Tipo estimado y distancia interna: no equivalen a identificar un instrumento ni a un porcentaje de parecido.",24,672,950,16,juce::Justification::centredLeft);
