        g.drawText("GAIN",760,650,45,20,juce::Justification::centredLeft);g.setColour(p.peak.load()>.98f?juce::Colour(0xffffb473):look.accent);g.drawText("Voces: "+juce::String(p.voiceCount.load()),970,670,126,18,juce::Justification::centredRight);
